// Local audio files are held in memory; project backups contain cue metadata only.
const sfxFiles=new Map();let activeMix=null,previewMixStart=0,previewAudioRequest=0,preparingAudio=false,audioMixGeneration=0;
function bounded(value,min,max,fallback=0){value=Number(value);return Number.isFinite(value)?Math.max(min,Math.min(max,value)):fallback}
function newCueId(){return 'cue-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9)}
function makeInput(label,value,type,onchange){const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement('input');input.type=type;input.value=value;if(type==='number'){input.min='0';input.step='.1'}input.oninput=()=>onchange(input.value);wrap.append(input);return wrap}
function refreshCaptionEditor(){
 const box=$('captionRows');box.replaceChildren();state.captions=state.captions||[];
 state.captions.forEach((cue,i)=>{let row=document.createElement('div');row.className='cue-card';row.append(makeInput('Caption '+(i+1),cue.text||'','text',v=>{cue.text=v.slice(0,200);changed()}));let times=document.createElement('div');times.className='row';times.append(makeInput('Start · seconds',cue.start,'number',v=>{cue.start=bounded(v,0,3600);changed()}),makeInput('End · seconds',cue.end,'number',v=>{cue.end=bounded(v,0,3600);changed()}));let remove=document.createElement('button');remove.className='text-button';remove.textContent='Remove caption';remove.onclick=()=>{state.captions.splice(i,1);refreshCaptionEditor();changed()};row.append(times,remove);box.append(row)});
}
$('addCaption').onclick=()=>{if(exporting)return;if(state.captions.length>=100){message('Maximum 100 captions per project.');return}const start=Math.min(duration()-.1,Math.floor(time*10)/10);state.captions.push({text:'Your caption here',start,end:Math.min(duration(),start+2)});refreshCaptionEditor();changed()};
function parseSrt(source){
 const stamp=s=>{const m=s.match(/^(\d+):(\d{2}):(\d{2})[,.](\d{1,3})$/);return m?Number(m[1])*3600+Number(m[2])*60+Number(m[3])+Number(m[4].padEnd(3,'0'))/1000:NaN};
 return source.replace(/^\uFEFF/,'').replace(/\r/g,'').trim().split(/\n\s*\n/).flatMap(block=>{const lines=block.split('\n');let k=lines.findIndex(l=>l.includes('-->'));if(k<0)return [];const ends=lines[k].split('-->').map(s=>s.trim().split(/\s/)[0]);let start=stamp(ends[0]),end=stamp(ends[1]),text=lines.slice(k+1).join(' ').replace(/<[^>]+>/g,'').slice(0,200);return Number.isFinite(start)&&Number.isFinite(end)&&end>start&&text?[{start,end,text}]:[]}).slice(0,100);
}
$('captionImport').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1024*1024)throw Error('Choose an SRT under 1 MB.');const cues=parseSrt(await file.text());if(!cues.length)throw Error('No valid timed captions found.');state.captions=cues;refreshCaptionEditor();changed();message(cues.length+' captions imported; previous captions were replaced.')}catch(err){message(err.message)}};
function refreshSfxEditor(){
 const box=$('sfxRows');box.replaceChildren();state.sfx=state.sfx||[];
 state.sfx.forEach(cue=>{let row=document.createElement('div');row.className='cue-card';const title=document.createElement('strong');title.textContent=cue.name||'Sound effect';const hint=document.createElement('p');hint.className='hint';hint.textContent=sfxFiles.has(cue.id)?'Audio file ready':'Reattach this audio file before exporting';row.append(title,hint);
  let attach=document.createElement('input');attach.type='file';attach.accept='audio/*';attach.setAttribute('aria-label','Attach '+(cue.name||'sound effect'));attach.onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>30*1024*1024){message('Use sound effects under 30 MB.');return}sfxFiles.set(cue.id,f);cue.name=f.name;refreshSfxEditor();changed()};row.append(attach);
  const times=document.createElement('div');times.className='row';for(const [label,key,def] of [['Start in video (s)','start',0],['Trim source start (s)','offset',0],['Length (s) · 0 = full','length',0],['Volume %','volume',80]])times.append(makeInput(label,cue[key]??def,'number',v=>{cue[key]=bounded(v,0,key==='volume'?100:3600,def);changed()}));row.append(times);
  const presets=document.createElement('div');presets.className='cue-presets';for(const [name,phase] of [['Upload',.5],['Loading',.5+.38*.45],['Reveal',.88]]){let b=document.createElement('button');b.textContent=name;b.onclick=()=>{cue.start=Math.round(duration()*phase*100)/100;refreshSfxEditor();changed();message('Sound timed to '+name.toLowerCase()+'. Presets match Couple collage with upload enabled.')};presets.append(b)}let remove=document.createElement('button');remove.className='text-button';remove.textContent='Remove SFX';remove.onclick=()=>{sfxFiles.delete(cue.id);state.sfx=state.sfx.filter(x=>x.id!==cue.id);refreshSfxEditor();changed()};row.append(presets,remove);box.append(row);
 });
}
$('sfxUpload').onchange=e=>{for(const file of e.target.files){if(state.sfx.length>=12){message('Maximum 12 sound effects per project.');break}if(file.size>30*1024*1024){message(file.name+' exceeds 30 MB.');continue}let id=newCueId();sfxFiles.set(id,file);state.sfx.push({id,name:file.name,start:0,offset:0,length:0,volume:80})}e.target.value='';refreshSfxEditor();changed()};
function drawCaptions(t){
 if(!$('captionsEnabled').checked)return;const cues=(state.captions||[]).filter(c=>t>=Number(c.start)&&t<Number(c.end)&&Number(c.end)>Number(c.start));if(!cues.length)return;
 const [w,h]=layoutSize();const size=bounded($('captionSize').value,18,64,32),max=w-80;ctx.save();setLayoutTransform();ctx.font=`700 ${size}px ${chosenFont($('textFont').value)}`;ctx.textAlign='center';ctx.textBaseline='top';
 const words=cues.map(c=>String(c.text)).join(' ').split(/\s+/),lines=[];let current='';for(const word of words){let next=current?current+' '+word:word;if(current&&ctx.measureText(next).width>max-24){lines.push(current);current=word}else current=next}if(current)lines.push(current);const shown=lines.slice(0,4),height=shown.length*size*1.25+24;let y=$('captionPosition').value==='top'?55:$('captionPosition').value==='middle'?(h-height)/2:h-height-75;y=Math.max(10,y);
 ctx.globalAlpha=.8;ctx.fillStyle=$('captionBackground').value;round(28,y,w-56,height,12);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=$('captionColor').value;shown.forEach((line,i)=>ctx.fillText(line,w/2,y+12+i*size*1.25,max));ctx.restore();
}
function stopAudioMix(){audioMixGeneration++;if(!activeMix)return;const mix=activeMix;activeMix=null;mix.nodes.forEach(n=>{try{n.stop()}catch{}});mix.context.close().catch(()=>{})}
async function prepareAudioMix(stream,preview=false,signal=null){
 stopAudioMix();const generation=audioMixGeneration,tracks=[];if(audioFile)tracks.push({file:audioFile,start:0,offset:bounded($('musicOffset').value,0,3600),length:0,volume:bounded($('musicVolume').value,0,100,70),loop:$('musicLoop').checked});
 if(state.endSfx){if(!endSfxFile)throw Error('Reattach your end-card SFX in step 7.');tracks.push({file:endSfxFile,...endSfxTiming()})}
 for(const cue of state.sfx||[]){const file=sfxFiles.get(cue.id);if(!file)throw Error('Reattach SFX: '+cue.name);tracks.push({...cue,file})}if(!tracks.length)return;
 const context=new AudioContext();await context.resume();if(signal?.aborted||generation!==audioMixGeneration){await context.close();throw new DOMException('Export cancelled','AbortError')}const destination=context.createMediaStreamDestination(),mix={context,destination,tracks:[],nodes:[],preview};activeMix=mix;
 try{for(const track of tracks){let buffer=await context.decodeAudioData(await track.file.arrayBuffer());if(activeMix!==mix){context.close().catch(()=>{});return}if(Number(track.offset)>=buffer.duration)throw Error('Trim start exceeds audio length: '+track.file.name);mix.tracks.push({...track,buffer})}
  if(stream)destination.stream.getAudioTracks().forEach(track=>stream.addTrack(track));
 }catch(err){stopAudioMix();throw err}
}
function cueSchedule(cue,from,videoDuration){
 const start=bounded(cue.start,0,3600),offset=bounded(cue.offset,0,3600),available=cue.buffer.duration-offset,length=Number(cue.length)>0?Math.min(available,Number(cue.length)):available,end=cue.loop?videoDuration:start+length;
 if(from>=end||start>=videoDuration)return null;const elapsed=Math.max(0,from-start),sourceOffset=cue.loop?offset+elapsed%available:offset+elapsed,when=Math.max(0,start-from),remaining=Math.min(end-Math.max(start,from),videoDuration-Math.max(start,from));return remaining>0?{when,offset:sourceOffset,duration:remaining}:null;
}
function beginAudioMix(from=0){const mix=activeMix;if(!mix)return;const now=mix.context.currentTime;for(const cue of mix.tracks){const timing=cueSchedule(cue,from,duration());if(!timing)continue;const node=mix.context.createBufferSource(),gain=mix.context.createGain();node.buffer=cue.buffer;node.loop=!!cue.loop;if(node.loop){node.loopStart=bounded(cue.offset,0,cue.buffer.duration);node.loopEnd=cue.buffer.duration}gain.gain.value=bounded(cue.volume,0,100,80)/100;node.connect(gain);gain.connect(mix.destination);if(mix.preview)gain.connect(mix.context.destination);node.start(now+timing.when,timing.offset,timing.duration);mix.nodes.push(node)}}
const renderWithEffects=render;render=function(t){renderWithEffects(t);drawCaptions(t);if(typeof stopFramedPlayback==='function'&&((!playing&&!exporting)||(state.template!=='framed'&&t<duration()*effectEnd())))stopFramedPlayback();if(activeMix?.preview&&(!playing||t<previewMixStart-.1))stopAudioMix()};
const originalPlay=$('play').onclick;$('play').onclick=async()=>{if(exporting||preparingAudio)return;if(playing){++previewAudioRequest;originalPlay();stopAudioMix();if(typeof stopFramedPlayback==='function')stopFramedPlayback();return}const request=++previewAudioRequest;preparingAudio=true;try{await prepareAudioMix(null,true);if(request!==previewAudioRequest){stopAudioMix();return}previewMixStart=time;originalPlay();beginAudioMix(time)}catch(err){message('Audio preview: '+err.message)}finally{preparingAudio=false}};
const originalRestart=$('restart').onclick;$('restart').onclick=()=>{++previewAudioRequest;stopAudioMix();playing=false;$('play').textContent='▶';originalRestart()};$('scrub').addEventListener('input',()=>{++previewAudioRequest;stopAudioMix()});
refreshCaptionEditor();refreshSfxEditor();
